const alias: Record<string, string> = {"Davao de Oro":"Compostela Valley","Davao de Oro (Compostela Valley)":"Compostela Valley","Davao del Norte":"Davao (davao Del Norte)","Cotabato":"Cotabato (north Cot.)","Cotabato (North Cotabato)":"Cotabato (north Cot.)","Mindoro Oriental":"Oriental Mindoro","Mindoro Occidental":"Occidental Mindoro","Samar":"Samar (western Samar)","Zamboanga City":"Zamboanga City","City of Isabela (not a province)":"Basilan","Metropolitan Manila First District":"Metropolitan Manila","Metropolitan Manila Second District":"Metropolitan Manila","Metropolitan Manila Third District":"Metropolitan Manila","Metropolitan Manila Fourth District":"Metropolitan Manila","Maguindanao del Norte":"Maguindanao","Maguindanao del Sur":"Maguindanao","Special Geographic Area":"Special Geographic Area"};

const norm = (s: string) => s.toLowerCase().replace(/[^a-z0-9 ]/g, "").trim();

/** Resolve a map path name to the dataset province entry (by display name). */
export function resolveProvince(mapName: string): Province | null {
  const key = alias[mapName] ?? mapName;
  if (key === "Special Geographic Area") {
    return { name: "Special Geographic Area", cities: [] };
  }
  for (const region of phRegions) {
    const province = region.provinces.find((p) => norm(p.name) === norm(key));
    if (province) return province;
  }
  return null;
}

/** Full detail for a selected map path: display name + region + province. */
export function findProvinceByMapName(mapName: string) {
  const province = resolveProvince(mapName);
  if (!province) return null;
  const region = phRegions.find((r) => r.provinces.some((p) => norm(p.name) === norm(province.name)));
  return { mapName, regionName: region?.name ?? null, province };
}

/** Look up by SVG id (e.g. PHMNL). */
export function findProvinceById(id: string) {
  const map = phMapProvinces.find((p) => p.id === id);
  if (!map) return null;
  return findProvinceByMapName(map.name);
}

/** Cities of a province entry, falling back to the province name for special areas. */
export function locationChoices(province: Province): string[] {
  return province.cities.length > 0 ? province.cities : [province.name];
}
